using var cache=new MemoryCache(new MemoryCacheOptions());
cache.Set("list",new List<int>{1});var a=cache.Get<List<int>>("list")!;a.Add(2);Console.WriteLine(cache.Get<List<int>>("list")!.Count);
cache.Remove("list");Console.WriteLine(cache.TryGetValue("list",out _));
var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);int calls=0;
async Task<int> Read()=>await cache.GetOrCreateAsync("key",async entry=>{entry.AbsoluteExpirationRelativeToNow=TimeSpan.FromMinutes(1);if(Interlocked.Increment(ref calls)==2)entered.SetResult();await release.Task;return 42;});
var first=Read();var second=Read();await entered.Task.WaitAsync(TimeSpan.FromSeconds(5));release.SetResult();await Task.WhenAll(first,second);Console.WriteLine("factory:"+calls);
using var gate=new SemaphoreSlim(1,1);int safeCalls=0;
async Task<int> SafeRead(){await gate.WaitAsync();try{return cache.GetOrCreate("safe",e=>{e.AbsoluteExpirationRelativeToNow=TimeSpan.FromMinutes(1);return ++safeCalls;});}finally{gate.Release();}}
await Task.WhenAll(SafeRead(),SafeRead());Console.WriteLine("safe-factory:"+safeCalls);

